/* eslint-disable */
var addSorting = (function() {
    'use strict';
    var cols,
        currentSort = {
            index: 0,
            desc: false
        };

    // returns the summary table element
    function getTable() {
        return document.querySelector('.coverage-summary');
    }
    // returns the thead element of the summary table
    function getTableHeader() {
        return getTable().querySelector('thead tr');
    }
    // returns the tbody element of the summary table
    function getTableBody() {
        return getTable().querySelector('tbody');
    }
    // returns the th element for nth column
    function getNthColumn(n) {
        return getTableHeader().querySelectorAll('th')[n];
    }

    function onFilterInput() {
        const searchValue = document.getElementById('fileSearch').value;
        const rows = document.getElementsByTagName('tbody')[0].children;

        // Try to create a RegExp from the searchValue. If it fails (invalid regex),
        // it will be treated as a plain text search
        let searchRegex;
        try {
            searchRegex = new RegExp(searchValue, 'i'); // 'i' for case-insensitive
        } catch (error) {
            searchRegex = null;
        }

        for (let i = 0; i < rows.length; i++) {
            const row = rows[i];
            let isMatch = false;

            if (searchRegex) {
                // If a valid regex was created, use it for matching
                isMatch = searchRegex.test(row.textContent);
            } else {
                // Otherwise, fall back to the original plain text search
                isMatch = row.textContent
                    .toLowerCase()
                    .includes(searchValue.toLowerCase());
            }

            row.style.display = isMatch ? '' : 'none';
        }
    }

    // loads the search box
    function addSearchBox() {
        var template = document.getElementById('filterTemplate');
        var templateClone = template.content.cloneNode(true);
        templateClone.getElementById('fileSearch').oninput = onFilterInput;
        template.parentElement.appendChild(templateClone);
    }

    // loads all columns
    function loadColumns() {
        var colNodes = getTableHeader().querySelectorAll('th'),
            colNode,
            cols = [],
            col,
            i;

        for (i = 0; i < colNodes.length; i += 1) {
            colNode = colNodes[i];
            col = {
                key: colNode.getAttribute('data-col'),
                sortable: !colNode.getAttribute('data-nosort'),
                type: colNode.getAttribute('data-type') || 'string'
            };
            cols.push(col);
            if (col.sortable) {
                col.defaultDescSort = col.type === 'number';
                colNode.innerHTML =
                    colNode.innerHTML + '<span class="sorter"></span>';
            }
        }
        return cols;
    }
    // attaches a data attribute to every tr element with an object
    // of data values keyed by column name
    function loadRowData(tableRow) {
        var tableCols = tableRow.querySelectorAll('td'),
            colNode,
            col,
            data = {},
            i,
            val;
        for (i = 0; i < tableCols.length; i += 1) {
            colNode = tableCols[i];
            col = cols[i];
            val = colNode.getAttribute('data-value');
            if (col.type === 'number') {
                val = Number(val);
            }
            data[col.key] = val;
        }
        return data;
    }
    // loads all row data
    function loadData() {
        var rows = getTableBody().querySelectorAll('tr'),
            i;

        for (i = 0; i < rows.length; i += 1) {
            rows[i].data = loadRowData(rows[i]);
        }
    }
    // sorts the table using the data for the ith column
    function sortByIndex(index, desc) {
        var key = cols[index].key,
            sorter = function(a, b) {
                a = a.data[key];
                b = b.data[key];
                return a < b ? -1 : a > b ? 1 : 0;
            },
            finalSorter = sorter,
            tableBody = document.querySelector('.coverage-summary tbody'),
            rowNodes = tableBody.querySelectorAll('tr'),
            rows = [],
            i;

        if (desc) {
            finalSorter = function(a, b) {
                return -1 * sorter(a, b);
            };
        }

        for (i = 0; i < rowNodes.length; i += 1) {
            rows.push(rowNodes[i]);
            tableBody.removeChild(rowNodes[i]);
        }

        rows.sort(finalSorter);

        for (i = 0; i < rows.length; i += 1) {
            tableBody.appendChild(rows[i]);
        }
    }
    // removes sort indicators for current column being sorted
    function removeSortIndicators() {
        var col = getNthColumn(currentSort.index),
            cls = col.className;

        cls = cls.replace(/ sorted$/, '').replace(/ sorted-desc$/, '');
        col.className = cls;
    }
    // adds sort indicators for current column being sorted
    function addSortIndicators() {
        getNthColumn(currentSort.index).className += currentSort.desc
            ? ' sorted-desc'
            : ' sorted';
    }
    // adds event listeners for all sorter widgets
    function enableUI() {
        var i,
            el,
            ithSorter = function ithSorter(i) {
                var col = cols[i];

                return function() {
                    var desc = col.defaultDescSort;

                    if (currentSort.index === i) {
                        desc = !currentSort.desc;
                    }
                    sortByIndex(i, desc);
                    removeSortIndicators();
                    currentSort.index = i;
                    currentSort.desc = desc;
                    addSortIndicators();
                };
            };
        for (i = 0; i < cols.length; i += 1) {
            if (cols[i].sortable) {
                // add the click event handler on the th so users
                // dont have to click on those tiny arrows
                el = getNthColumn(i).querySelector('.sorter').parentElement;
                if (el.addEventListener) {
                    el.addEventListener('click', ithSorter(i));
                } else {
                    el.attachEvent('onclick', ithSorter(i));
                }
            }
        }
    }
    // adds sorting functionality to the UI
    return function() {
        if (!getTable()) {
            return;
        }
        cols = loadColumns();
        loadData();
        addSearchBox();
        addSortIndicators();
        enableUI();
    };
})();

window.addEventListener('load', addSorting);

import { PrismaClient, Role } from '@prisma/client';
import bcrypt from 'bcryptjs';

const prisma = new PrismaClient();

async function main() {
  const passwordHash = await bcrypt.hash('123456', 10);

  // ── Usuario ADMIN ──────────────────────────────────────────────
  const admin = await prisma.user.upsert({
    where: { email: 'admin@uta.edu.ec' },
    update: {},
    create: {
      email: 'admin@uta.edu.ec',
      passwordHash,
      fullName: 'Administrador UTAxi',
      career: 'Administración',
      role: Role.ADMIN,
      emailVerified: true,
      status: 'ACTIVE',
    },
  });

  // ── Usuario STUDENT (normal) ───────────────────────────────────
  const student = await prisma.user.upsert({
    where: { email: 'estudiante@uta.edu.ec' },
    update: {},
    create: {
      email: 'estudiante@uta.edu.ec',
      passwordHash,
      fullName: 'Estudiante Prueba',
      career: 'Ingeniería en Sistemas',
      role: Role.STUDENT,
      emailVerified: true,
      status: 'ACTIVE',
    },
  });

  // ── Usuario de carga (Artillery) ──────────────────────────────
  const loadPasswordHash = await bcrypt.hash('LoadTest123!', 10);
  const loadUser = await prisma.user.upsert({
    where: { email: 'load-test@uta.edu.ec' },
    update: {},
    create: {
      email: 'load-test@uta.edu.ec',
      passwordHash: loadPasswordHash,
      fullName: 'Load Test User',
      career: 'Ingeniería en Sistemas',
      role: Role.STUDENT,
      emailVerified: true,
      status: 'ACTIVE',
    },
  });

  console.log('✅ Usuarios de prueba creados:');
  console.table([
    { id: admin.id,    email: admin.email,    role: admin.role,    verified: admin.emailVerified },
    { id: student.id,  email: student.email,  role: student.role,  verified: student.emailVerified },
    { id: loadUser.id, email: loadUser.email, role: loadUser.role, verified: loadUser.emailVerified },
  ]);
  console.log('\n🔑 Contraseña admin/student: 123456');
  console.log('🔑 Contraseña load-test:     LoadTest123!');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());

import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

async function verifyAllUsers() {
  try {
    console.log('🔄 Verificando todos los usuarios...');
    const result = await prisma.user.updateMany({
      data: {
        emailVerified: true,
        emailVerifyToken: null,
        emailVerifyExpiry: null,
      },
    });
    console.log(`✅ Se verificaron ${result.count} usuarios`);
  } catch (error: any) {
    console.error('❌ Error:', error.message);
  } finally {
    await prisma.$disconnect();
  }
}

verifyAllUsers();

import 'express-async-errors';
import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import cookieParser from 'cookie-parser';
import path from 'path';
import { env } from './config/env';
import { prisma } from './config/database';
import { errorHandler } from './middleware/errorHandler';
import { authRouter } from './routes/auth.routes';
import { usersRouter } from './routes/users.routes';
import { tripsRouter } from './routes/trips.routes';
import { requestsRouter } from './routes/requests.routes';
import { paymentsRouter } from './routes/payments.routes';
import { ratingsRouter } from './routes/ratings.routes';
import { reportsRouter } from './routes/reports.routes';
import { adminRouter } from './routes/admin.routes';

export function createApp() {
  const app = express();

  // ─── Seguridad y parsers ──────────────────────────────────────────────────
  app.use(helmet());
  app.use(
    cors({
      origin: env.FRONTEND_URL,
      credentials: true,
    }),
  );
  app.use(express.json());
  app.use(express.urlencoded({ extended: true }));
  app.use(cookieParser());

  // ─── Ruta raíz ───────────────────────────────────────────────────────────
  app.get('/', (_req, res) => {
    res.json({ message: 'API UTAxi - Servidor activo', version: '1.0.0' });
  });

















































































































































































































































  // ─── Health check ─────────────────────────────────────────────────────────
  app.get('/health', async (_req, res) => {
    try {
      await prisma.$queryRaw`SELECT 1`;
      res.json({ status: 'ok', db: 'connected', env: env.NODE_ENV });
    } catch {
      res.status(503).json({ status: 'error', db: 'disconnected' });
    }
  });

  // ─── Dev: Get verification code (solo en desarrollo) ─────────────────────
  if (env.NODE_ENV === 'development') {
    app.get('/api/dev/code/:email', async (req, res) => {
      const { email } = req.params;
      const user = await prisma.user.findUnique({ where: { email } });
      if (!user || !user.emailVerifyToken) {
        return res.status(404).json({ error: 'No hay código para este usuario' });
      }
      res.json({
        email,
        code: user.emailVerifyToken,
        expiresAt: user.emailVerifyExpiry,
      });
    });
  }

  // ─── Rutas API ────────────────────────────────────────────────────────────
  app.use('/api/auth', authRouter);
  app.use('/api/users', usersRouter);
  app.use('/api/trips', tripsRouter);
  app.use('/api/requests', requestsRouter);
  app.use('/api/payments', paymentsRouter);
  app.use('/api/ratings', ratingsRouter);
  app.use('/api/reports', reportsRouter);
  app.use('/api/admin', adminRouter);

  // ─── Archivos estáticos (evidencias de reportes) ──────────────────────────
  app.use('/uploads', express.static(path.join(process.cwd(), 'uploads')));

  // ─── 404 ──────────────────────────────────────────────────────────────────
  app.use((_req, res) => {
    res.status(404).json({ error: 'Ruta no encontrada' });
  });

  // ─── Error handler (debe ser el último middleware) ────────────────────────
  app.use(errorHandler);

  return app;
}

import nodemailer, { Transporter } from 'nodemailer';
import { env } from './env';

function createTransporter(): Transporter {
  // En desarrollo sin SMTP configurado → usa ethereal (logs en consola)
  if (!env.SMTP_USER || !env.SMTP_PASS) {
    return nodemailer.createTransport({
      host: 'localhost',
      port: 1025,
      ignoreTLS: true,
    });
  }

  return nodemailer.createTransport({
    host: env.SMTP_HOST,
    port: Number.parseInt(env.SMTP_PORT, 10),
    secure: false,
    auth: {
      user: env.SMTP_USER,
      pass: env.SMTP_PASS,
    },
  });
}

export const mailer = createTransporter();

export async function sendVerificationEmail(email: string, code: string): Promise<void> {
  // En desarrollo sin SMTP → solo log en consola
  if (!env.SMTP_USER || !env.SMTP_PASS) {
    console.log('\n─────────────────────────────────────');
    console.log(`📧 CÓDIGO DE VERIFICACIÓN para ${email}`);
    console.log(`   Código: ${code}`);
    console.log('─────────────────────────────────────\n');
    return;
  }

  await mailer.sendMail({
    from: `"U-Ride UTA" <${env.SMTP_USER}>`,
    to: email,
    subject: 'Verifica tu cuenta en U-Ride',
    html: `
      <div style="font-family: sans-serif; max-width: 480px; margin: 0 auto;">
        <h2 style="color: #1d4ed8;">Verifica tu cuenta en U-Ride</h2>
        <p>Usa el siguiente código para verificar tu correo institucional:</p>
        <div style="background: #f1f5f9; padding: 24px; text-align: center; border-radius: 8px; margin: 24px 0;">
          <span style="font-size: 36px; font-weight: bold; letter-spacing: 8px; color: #1d4ed8;">${code}</span>
        </div>
        <p style="color: #64748b; font-size: 14px;">Este código expira en 15 minutos. Si no solicitaste esto, ignora este correo.</p>
      </div>
    `,
  });
}

export async function sendPasswordResetEmail(email: string, code: string): Promise<void> {
  // En desarrollo sin SMTP → solo log en consola
  if (!env.SMTP_USER || !env.SMTP_PASS) {
    console.log('\n─────────────────────────────────────');
    console.log(`📧 CÓDIGO DE RECUPERACIÓN DE CONTRASEÑA para ${email}`);
    console.log(`   Código: ${code}`);
    console.log(`   Expira en: 15 minutos`);
    console.log('─────────────────────────────────────\n');
    return;
  }

  await mailer.sendMail({
    from: `"U-Ride UTA" <${env.SMTP_USER}>`,
    to: email,
    subject: 'Recupera tu contraseña en U-Ride',
    html: `
      <div style="font-family: sans-serif; max-width: 480px; margin: 0 auto;">
        <h2 style="color: #1d4ed8;">Recupera tu contraseña</h2>
