import { PrismaClient } from '@prisma/client';
import { AppError } from '../middleware/errorHandler';
import { hashPassword, comparePassword, generateOTP } from '../utils/hash';
import { signAccessToken, signRefreshToken, verifyRefreshToken } from '../utils/jwt';
import { sendVerificationEmail, sendPasswordResetEmail } from '../config/mailer';
import { env } from '../config/env';

const OTP_EXPIRY_MINUTES = 15;

export class AuthService {
  constructor(private readonly prisma: PrismaClient) {}

  async register(email: string, password: string, fullName: string, career?: string) {
    try {
      // Validar dominio institucional
      const domain = email.split('@')[1];
      if (domain !== env.ALLOWED_EMAIL_DOMAIN) {
        throw new AppError(400, `Solo se permiten correos @${env.ALLOWED_EMAIL_DOMAIN}`);
      }

      // Verificar que no exista
      const existing = await this.prisma.user.findUnique({ where: { email } });
      if (existing) {
        throw new AppError(409, 'Ya existe una cuenta con ese correo');
      }

      const passwordHash = await hashPassword(password);
      const code = generateOTP();
      const expiry = new Date(Date.now() + OTP_EXPIRY_MINUTES * 60 * 1000);

      await this.prisma.user.create({
        data: {
          email,
          passwordHash,
          fullName,
          career,
          emailVerifyToken: code,
          emailVerifyExpiry: expiry,
        },
      });

      await sendVerificationEmail(email, code);

      return { message: `Código de verificación enviado a ${email}` };
    } catch (error: any) {
      // Si es un AppError, relanzar
      if (error instanceof AppError) throw error;

      // Log de error detallado
      console.error('🔴 Error en register:', {
        message: error.message,
        code: error.code,
        email
      });

      // Errores de conexión a BD
      if (error.message.includes('Authentication failed')) {
        throw new AppError(503, 'No se puede conectar a la base de datos. Verifica que PostgreSQL esté corriendo en el puerto correcto.');
      }

      // Errores de constraint
      if (error.code === 'P2002') {
        throw new AppError(409, 'Ya existe una cuenta con ese correo');
      }

      throw new AppError(500, `Error al registrar: ${error.message}`);
    }
  }

  async verifyEmail(email: string, code: string) {
    const user = await this.prisma.user.findUnique({ where: { email } });

    if (!user) {
      throw new AppError(404, 'Usuario no encontrado');
    }
    if (user.emailVerified) {
      return { message: 'El correo ya fue verificado. Puedes iniciar sesión.' };
    }
    if (!user.emailVerifyToken || !user.emailVerifyExpiry) {
      throw new AppError(400, 'No hay código de verificación pendiente');
    }
    if (new Date() > user.emailVerifyExpiry) {
      throw new AppError(400, 'El código ha expirado. Vuelve a registrarte para obtener uno nuevo.');
    }
    if (user.emailVerifyToken !== code) {
      throw new AppError(400, 'Código incorrecto');
    }

    await this.prisma.user.update({
      where: { email },
      data: {
        emailVerified: true,
        emailVerifyToken: null,
        emailVerifyExpiry: null,
      },
    });

    return { message: 'Correo verificado correctamente. Ya puedes iniciar sesión.' };
  }

  async login(email: string, password: string) {
    try {
      const user = await this.prisma.user.findUnique({ where: { email } });

      if (!user) {
        throw new AppError(401, 'Credenciales inválidas');
      }
      if (!user.emailVerified) {
        throw new AppError(401, 'Debes verificar tu correo antes de iniciar sesión');
      }
      if (user.status === 'SUSPENDED') {
        throw new AppError(403, 'Tu cuenta está suspendida. Contacta al administrador.');
      }

      const valid = await comparePassword(password, user.passwordHash);
      if (!valid) {
        throw new AppError(401, 'Credenciales inválidas');
      }

      const payload = { userId: user.id, email: user.email, role: user.role };
      const accessToken = signAccessToken(payload);
      const refreshToken = signRefreshToken(payload);

      // Guardar refresh token hasheado en BD
      await this.prisma.user.update({
        where: { id: user.id },
        data: { refreshToken: await hashPassword(refreshToken) },
      });

      return {
        accessToken,
        refreshToken,
        user: {
          id: user.id,
          email: user.email,
          fullName: user.fullName,
          role: user.role,
          reputationScore: user.reputationScore,
        },
      };
    } catch (error: any) {
      // Si es un AppError, relanzar
      if (error instanceof AppError) throw error;

      console.error('🔴 Error en login:', {
        message: error.message,
        code: error.code,
        email
      });

      if (error.message.includes('Authentication failed')) {
        throw new AppError(503, 'No se puede conectar a la base de datos. Verifica que PostgreSQL esté corriendo.');
      }

      throw new AppError(500, `Error al iniciar sesión: ${error.message}`);
    }
  }

  async refresh(token: string) {
    let payload;
    try {
      payload = verifyRefreshToken(token);
    } catch {
      throw new AppError(401, 'Refresh token inválido o expirado');
    }

    const user = await this.prisma.user.findUnique({ where: { id: payload.userId } });
    if (!user || !user.refreshToken) {
      throw new AppError(401, 'Sesión no válida');
    }
    if (user.status === 'SUSPENDED') {
      throw new AppError(403, 'Tu cuenta está suspendida');
    }

    // Verificar que el token coincide con el almacenado
    const valid = await comparePassword(token, user.refreshToken);
    if (!valid) {
      throw new AppError(401, 'Refresh token inválido');
    }

    const newPayload = { userId: user.id, email: user.email, role: user.role };
    const accessToken = signAccessToken(newPayload);

    return { accessToken };
  }

  async logout(userId: string) {
    await this.prisma.user.update({
      where: { id: userId },
      data: { refreshToken: null },
    });
    return { message: 'Sesión cerrada correctamente' };
  }

  async resendVerificationCode(email: string) {
    try {
      const user = await this.prisma.user.findUnique({ where: { email } });

      if (!user) {
        throw new AppError(404, 'Usuario no encontrado');
      }

      if (user.emailVerified) {
        throw new AppError(400, 'Este correo ya ha sido verificado');
      }

      const code = generateOTP();
      const expiry = new Date(Date.now() + OTP_EXPIRY_MINUTES * 60 * 1000);

      await this.prisma.user.update({
        where: { email },
        data: {
          emailVerifyToken: code,
          emailVerifyExpiry: expiry,
        },
      });

      await sendVerificationEmail(email, code);

      return { message: `Código de verificación reenviado a ${email}` };
    } catch (error: any) {
      if (error instanceof AppError) throw error;

      console.error('🔴 Error en resendVerificationCode:', {
        message: error.message,
        email,
      });

      if (error.message?.includes('Authentication failed')) {
        throw new AppError(503, 'No se puede conectar a la base de datos.');
      }

      throw new AppError(500, `Error al reenviar código: ${error.message}`);
    }
  }

  async forgotPassword(email: string) {
    try {
      const user = await this.prisma.user.findUnique({ where: { email } });

      if (!user) {
        // No revelar si el usuario existe o no (por seguridad)
        return { message: 'Si la cuenta existe, recibirás un correo para recuperar tu contraseña' };
      }

      const code = generateOTP();
      const expiry = new Date(Date.now() + 15 * 60 * 1000); // 15 minutos

      await this.prisma.user.update({
        where: { email },
        data: {
          passwordResetToken: code,
          passwordResetExpiry: expiry,
        },
      });

      await sendPasswordResetEmail(email, code);

      return { message: 'Si la cuenta existe, recibirás un correo para recuperar tu contraseña' };
    } catch (error: any) {
      console.error('🔴 Error en forgotPassword:', {
        message: error.message,
        email,
      });

      if (error.message?.includes('Authentication failed')) {
        throw new AppError(503, 'No se puede conectar a la base de datos.');
      }

      throw new AppError(500, `Error al procesar: ${error.message}`);
    }
  }

  async resetPassword(email: string, code: string, newPassword: string) {
    try {
      const user = await this.prisma.user.findUnique({ where: { email } });

      if (!user) {
        throw new AppError(404, 'Usuario no encontrado');
      }
      if (!user.passwordResetToken || !user.passwordResetExpiry) {
        throw new AppError(400, 'No hay solicitud de recuperación pendiente. Solicita un nuevo código en "Olvidé mi contraseña".');
      }

      // Validar expiración con precisión
      const now = new Date();
      const expiryTime = new Date(user.passwordResetExpiry);
      const secondsExpired = Math.floor((now.getTime() - expiryTime.getTime()) / 1000);

      if (now > expiryTime) {
        // Limpiar token expirado para evitar bloqueos futuros
        await this.prisma.user.update({
          where: { email },
          data: {
            passwordResetToken: null,
            passwordResetExpiry: null,
          },
        });
        throw new AppError(400, `El código ha expirado (expiró hace ${secondsExpired} segundos). Solicita un nuevo código.`);
      }

      // Validar código (case-sensitive, sin espacios)
      const normalizedCode = code.trim();
      if (user.passwordResetToken !== normalizedCode) {
        throw new AppError(400, 'Código incorrecto. Verifica el código de 6 dígitos que recibiste en tu email.');
      }

      const passwordHash = await hashPassword(newPassword);

      await this.prisma.user.update({
        where: { email },
        data: {
          passwordHash,
          passwordResetToken: null,
          passwordResetExpiry: null,
        },
      });

      return { message: 'Contraseña recuperada correctamente. Ya puedes iniciar sesión.' };
    } catch (error: any) {
      // Si es un AppError, relanzar
      if (error instanceof AppError) throw error;

      console.error('🔴 Error en resetPassword:', {
        message: error.message,
        email,
      });

      throw new AppError(500, `Error al resetear: ${error.message}`);
    }
  }
}

import { PrismaClient, RequestStatus, PaymentStatus, TransactionType, TransactionConcept } from '@prisma/client';
import Stripe from 'stripe';
import { AppError } from '../middleware/errorHandler';

export class PaymentsService {
  constructor(
    private readonly prisma: PrismaClient,
    private readonly stripe: Stripe,
  ) {}

  async createIntent(tripRequestId: string, payerId: string) {
    const tripRequest = await this.prisma.tripRequest.findUnique({
      where: { id: tripRequestId },
      include: { trip: true },
    });

    if (!tripRequest) throw new AppError(404, 'Solicitud no encontrada');
    if (tripRequest.passengerId !== payerId) throw new AppError(403, 'Solo el pasajero puede pagar su solicitud');
    if (tripRequest.status !== RequestStatus.ACCEPTED) throw new AppError(400, 'Solo se puede pagar una solicitud aceptada');

    const existing = await this.prisma.payment.findUnique({ where: { tripRequestId } });
    if (existing && existing.status === PaymentStatus.CONFIRMED) {
      throw new AppError(409, 'Este viaje ya fue pagado');
    }

    const amountCents = Math.round(Number(tripRequest.trip.pricePerSeat) * 100);

    const intent = await this.stripe.paymentIntents.create({
      amount: amountCents,
      currency: 'usd',
      metadata: {
        tripRequestId,
        tripId: tripRequest.tripId,
        payerId,
      },
    });

    const payment = await this.prisma.payment.upsert({
      where: { tripRequestId },
      create: {
        tripRequestId,
        tripId: tripRequest.tripId,
        payerId,
        amount: tripRequest.trip.pricePerSeat,
        stripePaymentId: intent.id,
        status: PaymentStatus.PENDING,
      },
      update: {
        stripePaymentId: intent.id,
        status: PaymentStatus.PENDING,
      },
    });

    return {
      clientSecret: intent.client_secret,
      paymentId: payment.id,
      amount: Number(tripRequest.trip.pricePerSeat),
    };
  }

  async handleWebhook(payload: Buffer, signature: string, webhookSecret: string) {
    let event: Stripe.Event;

    try {
      event = this.stripe.webhooks.constructEvent(payload, signature, webhookSecret);
    } catch {
      throw new AppError(400, 'Firma del webhook inválida');
    }

    if (event.type === 'payment_intent.succeeded') {
      const intent = event.data.object as Stripe.PaymentIntent;
      await this.prisma.payment.updateMany({
        where: { stripePaymentId: intent.id },
        data: { status: PaymentStatus.CONFIRMED, confirmedAt: new Date() },
      });
    }

    if (event.type === 'payment_intent.payment_failed') {
      const intent = event.data.object as Stripe.PaymentIntent;
      await this.prisma.payment.updateMany({
        where: { stripePaymentId: intent.id },
        data: { status: PaymentStatus.FAILED },
      });
    }

    return { received: true };
  }

  async simulateConfirm(tripRequestId: string, payerId: string) {
    const tripRequest = await this.prisma.tripRequest.findUnique({
      where: { id: tripRequestId },
      include: { trip: true },
    });

    if (!tripRequest) throw new AppError(404, 'Solicitud no encontrada');
    if (tripRequest.passengerId !== payerId) throw new AppError(403, 'Solo el pasajero puede pagar su solicitud');
    if (tripRequest.status !== RequestStatus.ACCEPTED) throw new AppError(400, 'Solo se puede pagar una solicitud aceptada');

    const existing = await this.prisma.payment.findUnique({ where: { tripRequestId } });
    if (existing && existing.status === PaymentStatus.CONFIRMED) {
      throw new AppError(409, 'Este viaje ya fue pagado');
    }

    const payment = await this.prisma.payment.upsert({
      where: { tripRequestId },
      create: {
        tripRequestId,
        tripId: tripRequest.tripId,
        payerId,
        amount: tripRequest.trip.pricePerSeat,
        stripePaymentId: `sim_${Date.now()}`,
        status: PaymentStatus.CONFIRMED,
        confirmedAt: new Date(),
      },
      update: {
        status: PaymentStatus.CONFIRMED,
        confirmedAt: new Date(),
      },
    });

    return { payment, amount: Number(tripRequest.trip.pricePerSeat) };
  }

  async getByTripRequest(tripRequestId: string, userId: string) {
    const payment = await this.prisma.payment.findUnique({
      where: { tripRequestId },
      include: {
        trip: { select: { originZone: true, destinationZone: true, departureTime: true } },
      },
    });

    if (!payment) throw new AppError(404, 'Pago no encontrado');
    if (payment.payerId !== userId) throw new AppError(403, 'No tienes acceso a este pago');

    return payment;
  }

  async payWithWallet(tripRequestId: string, payerId: string) {
    const tripRequest = await this.prisma.tripRequest.findUnique({
      where: { id: tripRequestId },
      include: { trip: true, payment: true },
    });

    if (!tripRequest) throw new AppError(404, 'Solicitud no encontrada');
    if (tripRequest.passengerId !== payerId) throw new AppError(403, 'Solo el pasajero puede pagar su solicitud');
    if (tripRequest.status !== RequestStatus.ACCEPTED) throw new AppError(400, 'Solo se puede pagar una solicitud aceptada');
    if (tripRequest.payment?.status === PaymentStatus.CONFIRMED) throw new AppError(409, 'Esta solicitud ya fue pagada');

    const amount = tripRequest.trip.pricePerSeat;
    const driverId = tripRequest.trip.driverId;

    const payer = await this.prisma.user.findUnique({ where: { id: payerId }, select: { walletBalance: true } });
    if (!payer) throw new AppError(404, 'Usuario no encontrado');
    if (Number(payer.walletBalance) < Number(amount)) throw new AppError(400, 'Saldo insuficiente en U-Wallet');

    await this.prisma.$transaction([
      this.prisma.user.update({
        where: { id: payerId },
        data: { walletBalance: { decrement: amount } },
      }),
      this.prisma.user.update({
        where: { id: driverId },
        data: { pendingBalance: { increment: amount } },
      }),
      this.prisma.walletTransaction.create({
        data: {
          userId: payerId,
          amount,
          type: TransactionType.DEBIT,
          concept: TransactionConcept.PAYMENT,
          description: `${tripRequest.trip.originZone} → ${tripRequest.trip.destinationZone}`,
          relatedRequestId: tripRequestId,
        },
      }),
      this.prisma.payment.upsert({
        where: { tripRequestId },
        create: {
          tripRequestId,
          tripId: tripRequest.tripId,
          payerId,
          amount,
          status: PaymentStatus.CONFIRMED,
          confirmedAt: new Date(),
        },
        update: {
          status: PaymentStatus.CONFIRMED,
          confirmedAt: new Date(),
          stripePaymentId: null,
        },
      }),
    ]);

    return { amount: Number(amount) };
  }

  async getWallet(userId: string) {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      select: { walletBalance: true, pendingBalance: true },
    });
    if (!user) throw new AppError(404, 'Usuario no encontrado');

    const transactions = await this.prisma.walletTransaction.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
      take: 50,
    });

    return {
      walletBalance: Number(user.walletBalance),
      pendingBalance: Number(user.pendingBalance),
      transactions: transactions.map(t => ({ ...t, amount: Number(t.amount) })),
    };
  }

  async topUpWallet(userId: string, amount: number) {
    if (amount <= 0 || amount > 500) throw new AppError(400, 'El monto debe estar entre $0.01 y $500');

    await this.prisma.$transaction([
      this.prisma.user.update({
        where: { id: userId },
        data: { walletBalance: { increment: amount } },
      }),
      this.prisma.walletTransaction.create({
        data: {
          userId,
          amount,
          type: TransactionType.CREDIT,
          concept: TransactionConcept.TOPUP,
          description: 'Recarga manual',
        },
      }),
    ]);

    const updated = await this.prisma.user.findUnique({
      where: { id: userId },
      select: { walletBalance: true },
    });

    return { walletBalance: Number(updated!.walletBalance) };
  }
}

import { PrismaClient, ReportReason } from '@prisma/client';
import { AppError } from '../middleware/errorHandler';

export class ReportsService {
  constructor(private readonly prisma: PrismaClient) {}

  async create(reporterId: string, data: {
    reportedId: string;
    reason: ReportReason;
    description: string;
    evidenceUrls?: string[];
  }) {
    if (data.reportedId === reporterId) {
      throw new AppError(400, 'No puedes reportarte a ti mismo');
    }

    const reported = await this.prisma.user.findUnique({ where: { id: data.reportedId } });
    if (!reported) throw new AppError(404, 'Usuario reportado no encontrado');

    const report = await this.prisma.report.create({
      data: {
        reporterId,
        reportedId: data.reportedId,
        reason: data.reason,
        description: data.description,
        evidenceUrls: data.evidenceUrls ?? [],
      },
      include: {
        reported: { select: { id: true, fullName: true, email: true } },
      },
    });

    return report;
  }

  async getMyReports(reporterId: string) {
    return this.prisma.report.findMany({
      where: { reporterId },
      orderBy: { createdAt: 'desc' },
      include: {
        reported: { select: { id: true, fullName: true } },
        reviews: { select: { action: true, createdAt: true } },
      },
    });
  }
}

import { PrismaClient, RequestStatus, TripStatus, PaymentStatus, TransactionType, TransactionConcept } from '@prisma/client';
import { AppError } from '../middleware/errorHandler';

export class RequestsService {
  constructor(private readonly prisma: PrismaClient) {}

  async create(tripId: string, passengerId: string, message?: string) {
    const trip = await this.prisma.trip.findUnique({ where: { id: tripId } });
    if (!trip) throw new AppError(404, 'Viaje no encontrado');
    if (trip.driverId === passengerId) throw new AppError(403, 'El conductor no puede unirse a su propio viaje');
    if (trip.status !== TripStatus.SCHEDULED) throw new AppError(400, 'Solo se puede solicitar unirse a viajes en estado SCHEDULED');
    if (trip.availableSeats < 1) throw new AppError(400, 'No hay cupos disponibles en este viaje');

    const existing = await this.prisma.tripRequest.findUnique({
      where: { tripId_passengerId: { tripId, passengerId } },
    });

    if (existing) {
      if (existing.status === 'REJECTED') {
        if (existing.rejectionCount >= 3) {
          throw new AppError(400, 'Has alcanzado el límite de 3 rechazos para este viaje. Ya no puedes solicitar unirte.');
        }
        // Allow re-request: reset to PENDING (conflict checks below still apply)
        const updated = await this.prisma.tripRequest.update({
          where: { id: existing.id },
          data: { status: 'PENDING', message: message ?? existing.message },
          include: {
            passenger: { select: { id: true, fullName: true, career: true, reputationScore: true } },
            trip: { select: { id: true, originZone: true, destinationZone: true, departureTime: true } },
          },
        });
        return updated;
      }
      throw new AppError(400, 'Ya enviaste una solicitud para este viaje');
    }

    const bufferHours = 2;
    const bufferStart = new Date(trip.departureTime);
    bufferStart.setHours(bufferStart.getHours() - bufferHours);

    const bufferEnd = new Date(trip.departureTime);
    bufferEnd.setHours(bufferEnd.getHours() + bufferHours);

    // Check if user is driving another trip
    const conflictingDriverTrip = await this.prisma.trip.findFirst({
      where: {
        driverId: passengerId,
        status: { in: [TripStatus.SCHEDULED, TripStatus.IN_PROGRESS] },
        departureTime: {
          gte: bufferStart,
          lte: bufferEnd
        }
      }
    });

    if (conflictingDriverTrip) {
      throw new AppError(400, 'Ya tienes un viaje programado como conductor en ese horario (±2 horas). No puedes pedir este viaje.');
    }

    // Check if user is already a passenger in another overlapping trip
    const conflictingPassengerTrip = await this.prisma.tripRequest.findFirst({
      where: {
        passengerId,
        status: { in: ['ACCEPTED', 'PENDING'] },
        trip: {
          status: { in: [TripStatus.SCHEDULED, TripStatus.IN_PROGRESS] },
          departureTime: {
            gte: bufferStart,
            lte: bufferEnd
          }
        }
      }
    });

    if (conflictingPassengerTrip) {
      throw new AppError(400, 'Ya estás anotado o tienes solicitud pendiente en otro viaje para ese horario (±2 horas).');
    }

    const request = await this.prisma.tripRequest.create({
      data: { tripId, passengerId, message },
      include: {
        passenger: { select: { id: true, fullName: true, career: true, reputationScore: true } },
        trip: { select: { id: true, originZone: true, destinationZone: true, departureTime: true } },
      },
    });
    return request;
  }

  async getByTrip(tripId: string, driverId: string) {
    const trip = await this.prisma.trip.findUnique({ where: { id: tripId } });
    if (!trip) throw new AppError(404, 'Viaje no encontrado');
    if (trip.driverId !== driverId) throw new AppError(403, 'Solo el conductor puede ver las solicitudes de su viaje');

    const requests = await this.prisma.tripRequest.findMany({
      where: { tripId },
      orderBy: { createdAt: 'asc' },
      include: {
        passenger: {
          select: {
            id: true,
            fullName: true,
            career: true,
            neighborhood: true,
            reputationScore: true,
            totalTrips: true,
          },
        },
        ratings: { select: { id: true, score: true, raterId: true } },
      },
    });

    // Exponer solo el rating que hizo el conductor (para saber si ya calificó al pasajero)
    return requests.map(r => ({
      ...r,
      rating: r.ratings.find(rt => rt.raterId === driverId) ?? null,
    }));
  }

  async respond(requestId: string, driverId: string, action: 'ACCEPT' | 'REJECT') {
    const request = await this.prisma.tripRequest.findUnique({
      where: { id: requestId },
      include: { trip: true },
    });
    if (!request) throw new AppError(404, 'Solicitud no encontrada');
    if (request.trip.driverId !== driverId) throw new AppError(403, 'Solo el conductor puede gestionar solicitudes');
    if (request.status !== RequestStatus.PENDING) throw new AppError(400, `La solicitud ya fue ${request.status === RequestStatus.ACCEPTED ? 'aceptada' : 'rechazada'}`);

    if (action === 'ACCEPT') {
      if (request.trip.availableSeats < 1) throw new AppError(400, 'No hay cupos disponibles');

      const [updated] = await this.prisma.$transaction([
        this.prisma.tripRequest.update({
          where: { id: requestId },
          data: { status: RequestStatus.ACCEPTED },
          include: {
            passenger: { select: { id: true, fullName: true } },
            trip: { select: { id: true, destinationZone: true, departureTime: true, availableSeats: true } },
          },
        }),
        this.prisma.trip.update({
          where: { id: request.tripId },
          data: { availableSeats: { decrement: 1 } },
        }),
      ]);
      return updated;
    }

    return this.prisma.tripRequest.update({
      where: { id: requestId },
      data: {
        status: RequestStatus.REJECTED,
        rejectionCount: { increment: 1 },
      },
      include: {
        passenger: { select: { id: true, fullName: true } },
      },
    });
  }

  async cancelRequest(requestId: string, passengerId: string) {
    const request = await this.prisma.tripRequest.findUnique({
      where: { id: requestId },
      include: { trip: true, payment: true },
    });

    if (!request) throw new AppError(404, 'Solicitud no encontrada');
    if (request.passengerId !== passengerId) throw new AppError(403, 'No puedes cancelar una solicitud que no es tuya');
    if (request.status === RequestStatus.CANCELLED) throw new AppError(400, 'La solicitud ya fue cancelada');
    if (request.trip.status === TripStatus.IN_PROGRESS) throw new AppError(400, 'No puedes cancelar mientras el viaje está en curso');
    if (request.trip.status === TripStatus.COMPLETED) throw new AppError(400, 'El viaje ya fue completado');

    // PENDING: cancelación simple sin cupo ni pago involucrado
    if (request.status === RequestStatus.PENDING) {
      await this.prisma.tripRequest.update({
        where: { id: requestId },
        data: { status: RequestStatus.CANCELLED },
      });
      return { refunded: false, message: 'Solicitud cancelada' };
    }

    // ACCEPTED sin pago: devolver cupo y listo
    if (!request.payment || request.payment.status !== PaymentStatus.CONFIRMED) {
      await this.prisma.$transaction([
        this.prisma.tripRequest.update({
          where: { id: requestId },
          data: { status: RequestStatus.CANCELLED },
        }),
        this.prisma.trip.update({
          where: { id: request.tripId },
          data: { availableSeats: { increment: 1 } },
        }),
      ]);
      return { refunded: false, message: 'Reserva cancelada y cupo devuelto al viaje' };
    }

    // ACCEPTED con pago confirmado: aplicar política de cancelación
    const minutesUntilDeparture = (new Date(request.trip.departureTime).getTime() - Date.now()) / 60_000;
    const amount = request.payment.amount;
    const driverId = request.trip.driverId;

    // Regla 1: ventana de gracia de 30 min si el conductor cambió la hora recientemente
    const withinGracePeriod = !!request.trip.departureTimeChangedAt &&
      (Date.now() - new Date(request.trip.departureTimeChangedAt).getTime()) < 30 * 60_000;

    if (minutesUntilDeparture >= 10 || withinGracePeriod) {
      // Dentro del plazo: reembolso total al wallet del pasajero
      await this.prisma.$transaction([
        this.prisma.tripRequest.update({
          where: { id: requestId },
          data: { status: RequestStatus.CANCELLED },
        }),
        this.prisma.trip.update({
          where: { id: request.tripId },
          data: { availableSeats: { increment: 1 } },
        }),
        this.prisma.payment.update({
          where: { id: request.payment.id },
          data: { status: PaymentStatus.REFUNDED },
        }),
        this.prisma.user.update({
          where: { id: passengerId },
          data: { walletBalance: { increment: amount } },
        }),
        this.prisma.user.update({
          where: { id: driverId },
          data: { pendingBalance: { decrement: amount } },
        }),
        this.prisma.walletTransaction.create({
          data: {
            userId: passengerId,
            amount,
            type: TransactionType.CREDIT,
            concept: TransactionConcept.REFUND,
            description: `${request.trip.originZone} → ${request.trip.destinationZone}`,
            relatedRequestId: requestId,
          },
        }),
      ]);
      return {
        refunded: true,
        amount: Number(amount),
        message: withinGracePeriod
          ? `Cancelación por cambio de horario. Se reembolsaron $${Number(amount).toFixed(2)} a tu U-Wallet`
          : `Se reembolsaron $${Number(amount).toFixed(2)} a tu U-Wallet`,
      };
    }

    // Fuera del plazo: el conductor se queda con el dinero como compensación
    await this.prisma.$transaction([
      this.prisma.tripRequest.update({
        where: { id: requestId },
        data: { status: RequestStatus.CANCELLED },
      }),
      this.prisma.trip.update({
        where: { id: request.tripId },
        data: { availableSeats: { increment: 1 } },
      }),
      this.prisma.user.update({
        where: { id: driverId },
        data: {
          pendingBalance: { decrement: amount },
          walletBalance: { increment: amount },
        },
      }),
      this.prisma.walletTransaction.create({
        data: {
          userId: driverId,
          amount,
          type: TransactionType.CREDIT,
          concept: TransactionConcept.CANCELLATION_FEE,
          description: `${request.trip.originZone} → ${request.trip.destinationZone}`,
          relatedRequestId: requestId,
        },
      }),
    ]);
    return {
      refunded: false,
      message: 'Cancelación fuera del plazo permitido. No se realizó reembolso.',
    };
  }

  async markArrival(requestId: string, driverId: string, arrived: boolean) {
    const request = await this.prisma.tripRequest.findUnique({
      where: { id: requestId },
      include: { trip: true },
    });
    if (!request) throw new AppError(404, 'Solicitud no encontrada');
    if (request.trip.driverId !== driverId) throw new AppError(403, 'Solo el conductor puede registrar llegadas');
    if (request.status !== 'ACCEPTED') throw new AppError(400, 'Solo se puede registrar llegada de pasajeros aceptados');

    const updated = await this.prisma.tripRequest.update({
      where: { id: requestId },
      data: { arrivedAt: arrived ? new Date() : null },
    });
    return updated;
  }

  async getMyRequests(passengerId: string) {
    const requests = await this.prisma.tripRequest.findMany({
      where: { passengerId },
      orderBy: { createdAt: 'desc' },
      include: {
        trip: {
          include: {
            driver: { select: { id: true, fullName: true, reputationScore: true } },
          },
        },
        ratings: { select: { id: true, score: true, comment: true, raterId: true } },
        payment: { select: { id: true, amount: true, status: true, confirmedAt: true } },
      },
    });

    return requests.map(r => ({
      ...r,
      // Exponer solo el rating que hizo el propio pasajero (para saber si ya calificó al conductor)
      rating: r.ratings.find(rt => rt.raterId === passengerId) ?? null,
      payment: r.payment ? { ...r.payment, amount: Number(r.payment.amount) } : null,
    }));
  }
}

import { PrismaClient, TripStatus, PaymentStatus, TransactionType, TransactionConcept, RequestStatus, Prisma } from '@prisma/client';
import { AppError } from '../middleware/errorHandler';
import { emitToUser } from '../socket/tracking.gateway';

export class TripsService {
  constructor(private readonly prisma: PrismaClient) {}

  async create(driverId: string, data: {
    originZone: string;
    originLat?: number;
    originLng?: number;
    destinationZone: string;
    destLat?: number;
    destLng?: number;
    departureTime: Date;
    totalSeats: number;
    pricePerSeat: number;
    notes?: string;
    rules?: string;
  }) {
    const bufferHours = 2;
    const bufferStart = new Date(data.departureTime);
    bufferStart.setHours(bufferStart.getHours() - bufferHours);

    const bufferEnd = new Date(data.departureTime);
    bufferEnd.setHours(bufferEnd.getHours() + bufferHours);

    // Check if user is driving another trip at that time
    const conflictingDriverTrip = await this.prisma.trip.findFirst({
      where: {
        driverId,
        status: { in: [TripStatus.SCHEDULED, TripStatus.IN_PROGRESS] },
        departureTime: {
          gte: bufferStart,
          lte: bufferEnd
        }
      }
    });

    if (conflictingDriverTrip) {
      throw new AppError(400, 'Ya tienes un viaje programado como conductor en ese horario (±2 horas). No puedes crear viajes simultáneos.');
    }

    // Check if user is a passenger in another trip at that time
    const conflictingPassengerTrip = await this.prisma.tripRequest.findFirst({
      where: {
        passengerId: driverId,
        status: { in: ['ACCEPTED', 'PENDING'] },
        trip: {
          status: { in: [TripStatus.SCHEDULED, TripStatus.IN_PROGRESS] },
          departureTime: {
            gte: bufferStart,
            lte: bufferEnd
          }
        }
      }
    });

    if (conflictingPassengerTrip) {
      throw new AppError(400, 'Ya tienes una solicitud de pasajero en otro viaje para ese horario (±2 horas). No puedes ser conductor simultáneamente.');
    }

    const trip = await this.prisma.trip.create({
      data: {
        driverId,
        ...data,
        availableSeats: data.totalSeats,
      },
      include: { driver: { select: { id: true, fullName: true, reputationScore: true } } },
    });
    return trip;
  }

  async findMany(filters: {
    destinationZone?: string;
    departureDate?: string;
    minSeats?: number;
    status?: TripStatus;
    driverId?: string;
    page?: number;
    limit?: number;
  }) {
    const page = filters.page ?? 1;
    const limit = Math.min(filters.limit ?? 10, 50);
    const skip = (page - 1) * limit;

    const where: any = {};

    if (filters.destinationZone) {
      where.destinationZone = { contains: filters.destinationZone, mode: 'insensitive' };
    }
    if (filters.departureDate) {
      const date = new Date(filters.departureDate);
      const next = new Date(date);
      next.setDate(next.getDate() + 1);
      where.departureTime = { gte: date, lt: next };
    }
    if (filters.minSeats) {
      where.availableSeats = { gte: Number(filters.minSeats) };
    }
    if (filters.driverId) {
      where.driverId = filters.driverId;
    }

    if (filters.status) {
      where.status = filters.status;
    } else if (!filters.driverId) {
      where.status = TripStatus.SCHEDULED;
    }

    const [trips, total] = await this.prisma.$transaction([
      this.prisma.trip.findMany({
        where,
        skip,
        take: limit,
        orderBy: { departureTime: 'asc' },
        include: {
          driver: {
            select: {
              id: true,
              fullName: true,
              reputationScore: true,
              vehicle: { select: { brand: true, model: true, color: true } },
            },
          },
        },
      }),
      this.prisma.trip.count({ where }),
    ]);

    return { trips, total, page, limit };
  }

  async findById(tripId: string) {
    const trip = await this.prisma.trip.findUnique({
      where: { id: tripId },
      include: {
        driver: {
          select: {
            id: true,
            fullName: true,
            career: true,
            reputationScore: true,
            totalTrips: true,
            vehicle: { select: { brand: true, model: true, year: true, color: true, plateNumber: true } },
          },
        },
        _count: { select: { requests: { where: { status: 'ACCEPTED' } } } },
      },
    });

    if (!trip) throw new AppError(404, 'Viaje no encontrado');
    return trip;
  }

  async update(tripId: string, driverId: string, data: {
    originZone?: string;
    originLat?: number;
    originLng?: number;
    destinationZone?: string;
    destLat?: number;
    destLng?: number;
    departureTime?: Date;
    totalSeats?: number;
    pricePerSeat?: number;
    notes?: string;
    rules?: string;
  }) {
    const trip = await this.prisma.trip.findUnique({ where: { id: tripId } });
    if (!trip) throw new AppError(404, 'Viaje no encontrado');
    if (trip.driverId !== driverId) throw new AppError(403, 'No tienes permiso para editar este viaje');
    if (trip.status !== TripStatus.SCHEDULED) throw new AppError(400, 'Solo se pueden editar viajes en estado SCHEDULED');

    const hasPaidPassenger = await this.prisma.tripRequest.findFirst({
      where: {
        tripId,
        status: RequestStatus.ACCEPTED,
        payment: { status: PaymentStatus.CONFIRMED },
      },
    });

    // Regla 4: precio bloqueado si hay pagos confirmados
    if (hasPaidPassenger && data.pricePerSeat !== undefined) {
      throw new AppError(400, 'No se puede cambiar el precio: hay pasajeros que ya pagaron');
    }

    // Regla 2: no se puede adelantar la hora si hay pagos confirmados
    if (hasPaidPassenger && data.departureTime !== undefined) {
      if (data.departureTime < trip.departureTime) {
        throw new AppError(400, 'No se puede adelantar la hora de salida: hay pasajeros que ya pagaron');
      }
    }

    const changingTime = data.departureTime !== undefined &&
      data.departureTime.getTime() !== trip.departureTime.getTime();

    const updateData: any = { ...data };

    if (changingTime) {
      updateData.departureTimeChangedAt = new Date();

      // Regla 3: si el cambio es >60 min, registrar deadline de re-confirmación en cada request pagada
      const diffMinutes = Math.abs(
        (data.departureTime!.getTime() - trip.departureTime.getTime()) / 60_000,
      );

      if (diffMinutes > 60 && hasPaidPassenger) {
        const deadline = new Date(Date.now() + 30 * 60_000);
        await this.prisma.tripRequest.updateMany({
          where: {
            tripId,
            status: RequestStatus.ACCEPTED,
            payment: { status: PaymentStatus.CONFIRMED },
          },
          data: { scheduleChangeDeadline: deadline },
        });
      }
    }

    const updated = await this.prisma.trip.update({
      where: { id: tripId },
      data: updateData,
      include: {
        requests: {
          where: { status: RequestStatus.ACCEPTED },
          select: { id: true, passenger: { select: { id: true } } },
        },
      },
    });

    // Notificar a pasajeros si cambió la hora
    if (changingTime) {
      const bigChange = Math.abs(
        (data.departureTime!.getTime() - trip.departureTime.getTime()) / 60_000,
      ) > 60;

      for (const req of updated.requests) {
        emitToUser(req.passenger.id, 'trip:schedule-changed', {
          tripId,
          requestId: req.id,
          originZone: updated.originZone,
          destinationZone: updated.destinationZone,
          oldTime: trip.departureTime.toISOString(),
          newTime: data.departureTime!.toISOString(),
          bigChange,
        });
      }
    }

    // No exponer la lista de requests en la respuesta
    const { requests: _r, ...result } = updated;
    return result;
  }

  async cancel(tripId: string, driverId: string) {
    const trip = await this.prisma.trip.findUnique({ where: { id: tripId } });
    if (!trip) throw new AppError(404, 'Viaje no encontrado');
    if (trip.driverId !== driverId) throw new AppError(403, 'No tienes permiso para cancelar este viaje');
    if (trip.status === TripStatus.COMPLETED) throw new AppError(400, 'No se puede cancelar un viaje completado');
    if (trip.status === TripStatus.CANCELLED) throw new AppError(400, 'El viaje ya está cancelado');

    const activeRequests = await this.prisma.tripRequest.findMany({
      where: { tripId, status: { in: [RequestStatus.ACCEPTED, RequestStatus.PENDING] } },
      include: {
        payment: true,
        passenger: { select: { id: true } },
      },
    });

    const paidRequests = activeRequests.filter(r => r.payment?.status === PaymentStatus.CONFIRMED);

    const ops: Prisma.PrismaPromise<unknown>[] = [
      this.prisma.trip.update({ where: { id: tripId }, data: { status: TripStatus.CANCELLED } }),
      this.prisma.tripRequest.updateMany({
        where: { tripId, status: { in: [RequestStatus.ACCEPTED, RequestStatus.PENDING] } },
        data: { status: RequestStatus.CANCELLED },
      }),
    ];

    // Regla 5: reembolso total a cada pasajero que pagó
    for (const r of paidRequests) {
      const amount = r.payment!.amount;
      ops.push(
        this.prisma.payment.update({
          where: { id: r.payment!.id },
          data: { status: PaymentStatus.REFUNDED },
        }),
        this.prisma.user.update({
          where: { id: r.passenger.id },
          data: { walletBalance: { increment: amount } },
        }),
        this.prisma.user.update({
          where: { id: driverId },
          data: { pendingBalance: { decrement: amount } },
        }),
        this.prisma.walletTransaction.create({
          data: {
            userId: r.passenger.id,
            amount,
            type: TransactionType.CREDIT,
            concept: TransactionConcept.REFUND,
            description: `Viaje cancelado: ${trip.originZone} → ${trip.destinationZone}`,
            relatedRequestId: r.id,
          },
        }),
      );
    }

    await this.prisma.$transaction(ops);

    // Notificar a todos los pasajeros activos
    for (const r of activeRequests) {
      const refundAmount = paidRequests.find(p => p.id === r.id)?.payment?.amount;
      emitToUser(r.passenger.id, 'trip:cancelled-by-driver', {
        tripId,
        originZone: trip.originZone,
        destinationZone: trip.destinationZone,
        refundAmount: refundAmount ? Number(refundAmount) : 0,
      });
    }

    return this.prisma.trip.findUnique({ where: { id: tripId } });
  }

  async updateStatus(tripId: string, driverId: string, status: TripStatus) {
    const trip = await this.prisma.trip.findUnique({
      where: { id: tripId },
      include: { driver: { select: { fullName: true } } },
    });
    if (!trip) throw new AppError(404, 'Viaje no encontrado');
    if (trip.driverId !== driverId) throw new AppError(403, 'No tienes permiso para modificar este viaje');

    const allowed: Record<TripStatus, TripStatus[]> = {
      SCHEDULED:   [TripStatus.CANCELLED],
      IN_PROGRESS: [TripStatus.COMPLETED],
      COMPLETED:   [],
      CANCELLED:   [],
    };
    if (!allowed[trip.status].includes(status)) {
      if (status === TripStatus.IN_PROGRESS && trip.status === TripStatus.SCHEDULED) {
        throw new AppError(400, 'Para iniciar el viaje usa POST /trips/:id/start con la lista de asistencia');
      }
      throw new AppError(400, `No se puede pasar de ${trip.status} a ${status}`);
    }

    if (status !== TripStatus.COMPLETED) {
      return this.prisma.trip.update({ where: { id: tripId }, data: { status } });
    }

    // Al completar: flush de escrow → walletBalance del conductor
    const acceptedRequests = await this.prisma.tripRequest.findMany({
      where: { tripId, status: 'ACCEPTED' },
      include: {
        payment: true,
        passenger: { select: { id: true, fullName: true } },
      },
    });

    const paidRequests = acceptedRequests.filter(r => r.payment?.status === PaymentStatus.CONFIRMED);

    const totalEarned = paidRequests.reduce(
      (sum, r) => sum + Number(r.payment!.amount),
      0,
    );

    await this.prisma.$transaction([
      this.prisma.trip.update({ where: { id: tripId }, data: { status } }),
      // Marcar todas las solicitudes aceptadas como COMPLETED
      this.prisma.tripRequest.updateMany({
        where: { tripId, status: RequestStatus.ACCEPTED },
        data: { status: RequestStatus.COMPLETED },
      }),
      this.prisma.user.update({
        where: { id: driverId },
        data: {
          pendingBalance: { decrement: totalEarned },
          walletBalance: { increment: totalEarned },
          totalTrips: { increment: 1 },
        },
      }),
      ...paidRequests.map(r =>
        this.prisma.walletTransaction.create({
          data: {
            userId: driverId,
            amount: r.payment!.amount,
            type: TransactionType.CREDIT,
            concept: TransactionConcept.TRIP_EARNING,
            description: `${trip.originZone} → ${trip.destinationZone}`,
            relatedRequestId: r.id,
          },
        }),
      ),
    ]);

    const completedTrip = await this.prisma.trip.findUnique({ where: { id: tripId } });

    // Notificar a cada pasajero para que califiquen al conductor
    for (const req of acceptedRequests) {
      emitToUser(req.passenger.id, 'trip:completed', {
        tripId,
        requestId: req.id,
        driverName: trip.driver.fullName,
        originZone: trip.originZone,
        destinationZone: trip.destinationZone,
      });
    }

    // Notificar al conductor con la lista de pasajeros a calificar
    emitToUser(driverId, 'trip:completed', {
      tripId,
      passengers: acceptedRequests.map(r => ({
        requestId: r.id,
        name: r.passenger.fullName,
      })),
    });

    return completedTrip;
  }

  async confirmSchedule(tripId: string, passengerId: string) {
    const request = await this.prisma.tripRequest.findFirst({
      where: { tripId, passengerId, status: RequestStatus.ACCEPTED },
    });
    if (!request) throw new AppError(404, 'No tienes una reserva activa en este viaje');
    if (!request.scheduleChangeDeadline) throw new AppError(400, 'No hay cambio de horario pendiente de confirmación');
    if (new Date() > request.scheduleChangeDeadline) {
      throw new AppError(400, 'El plazo para confirmar el nuevo horario ha expirado');
    }

    await this.prisma.tripRequest.update({
      where: { id: request.id },
      data: { scheduleChangeDeadline: null },
    });

    return { confirmed: true };
  }

  async startTrip(tripId: string, driverId: string, boardedRequestIds: string[]) {
    const trip = await this.prisma.trip.findUnique({
      where: { id: tripId },
      include: { driver: { select: { fullName: true } } },
    });
    if (!trip) throw new AppError(404, 'Viaje no encontrado');
    if (trip.driverId !== driverId) throw new AppError(403, 'No tienes permiso para iniciar este viaje');
    if (trip.status !== TripStatus.SCHEDULED) throw new AppError(400, 'Solo se pueden iniciar viajes en estado SCHEDULED');

    // Regla 3: auto-cancelar pasajeros con deadline de re-confirmación expirado
    const expiredConfirmations = await this.prisma.tripRequest.findMany({
      where: {
        tripId,
        status: RequestStatus.ACCEPTED,
        scheduleChangeDeadline: { lt: new Date() },
      },
      include: {
        payment: true,
        passenger: { select: { id: true } },
      },
    });

    if (expiredConfirmations.length > 0) {
      const expiredOps: Prisma.PrismaPromise<unknown>[] = [];

      for (const r of expiredConfirmations) {
        expiredOps.push(
          this.prisma.tripRequest.update({
            where: { id: r.id },
            data: { status: RequestStatus.CANCELLED },
          }),
        );

        if (r.payment?.status === PaymentStatus.CONFIRMED) {
          const amount = r.payment.amount;
          expiredOps.push(
            this.prisma.payment.update({
              where: { id: r.payment.id },
              data: { status: PaymentStatus.REFUNDED },
            }),
            this.prisma.user.update({
              where: { id: r.passenger.id },
              data: { walletBalance: { increment: amount } },
            }),
            this.prisma.user.update({
              where: { id: driverId },
              data: { pendingBalance: { decrement: amount } },
            }),
            this.prisma.walletTransaction.create({
              data: {
                userId: r.passenger.id,
                amount,
                type: TransactionType.CREDIT,
                concept: TransactionConcept.REFUND,
                description: `No confirmó cambio de horario: ${trip.originZone} → ${trip.destinationZone}`,
                relatedRequestId: r.id,
              },
            }),
          );
        }
      }

      await this.prisma.$transaction(expiredOps);

      for (const r of expiredConfirmations) {
        const hadPayment = r.payment?.status === PaymentStatus.CONFIRMED;
        emitToUser(r.passenger.id, 'request:cancelled-no-show', {
          tripId,
          requestId: r.id,
          driverName: trip.driver.fullName,
          originZone: trip.originZone,
          destinationZone: trip.destinationZone,
          refunded: hadPayment,
        });
      }
    }

    const acceptedRequests = await this.prisma.tripRequest.findMany({
      where: { tripId, status: RequestStatus.ACCEPTED },
      include: {
        payment: true,
        passenger: { select: { id: true, fullName: true } },
      },
    });

    if (acceptedRequests.length === 0) throw new AppError(400, 'No hay pasajeros aceptados en este viaje');

    const boardedSet = new Set(boardedRequestIds);
    const boarded  = acceptedRequests.filter(r =>  boardedSet.has(r.id));
    const noShows  = acceptedRequests.filter(r => !boardedSet.has(r.id));

    const noShowsPaid   = noShows.filter(r => r.payment?.status === PaymentStatus.CONFIRMED);
    const noShowsUnpaid = noShows.filter(r => !r.payment || r.payment.status !== PaymentStatus.CONFIRMED);

    const ops: Prisma.PrismaPromise<unknown>[] = [
      this.prisma.trip.update({ where: { id: tripId }, data: { status: TripStatus.IN_PROGRESS } }),
      ...boarded.map(r =>
        this.prisma.tripRequest.update({ where: { id: r.id }, data: { arrivedAt: new Date() } }),
      ),
      ...noShowsUnpaid.map(r =>
        this.prisma.tripRequest.update({ where: { id: r.id }, data: { status: RequestStatus.CANCELLED } }),
      ),
    ];

    // No-show con pago: conductor se queda el dinero (equivalente a cancelación <10 min)
    for (const r of noShowsPaid) {
      const amount = r.payment!.amount;
      ops.push(
        this.prisma.tripRequest.update({ where: { id: r.id }, data: { status: RequestStatus.CANCELLED } }),
        this.prisma.user.update({
          where: { id: driverId },
          data: { pendingBalance: { decrement: amount }, walletBalance: { increment: amount } },
        }),
        this.prisma.walletTransaction.create({
          data: {
            userId: driverId,
            amount,
            type: TransactionType.CREDIT,
            concept: TransactionConcept.CANCELLATION_FEE,
            description: `No-show: ${trip.originZone} → ${trip.destinationZone}`,
            relatedRequestId: r.id,
          },
        }),
      );
    }

    await this.prisma.$transaction(ops);

    for (const r of noShows) {
      emitToUser(r.passenger.id, 'request:cancelled-no-show', {
        tripId,
        requestId: r.id,
        driverName: trip.driver.fullName,
        originZone: trip.originZone,
        destinationZone: trip.destinationZone,
        refunded: false,
      });
    }

    return this.prisma.trip.findUnique({ where: { id: tripId } });
  }

  async safetyAck(tripId: string, userId: string) {
    const trip = await this.prisma.trip.findUnique({ where: { id: tripId } });
    if (!trip) throw new AppError(404, 'Viaje no encontrado');

    await this.prisma.safetyAcknowledgment.upsert({
      where: { userId_tripId: { userId, tripId } },
      create: { userId, tripId },
      update: {},
    });

    return { acknowledged: true };
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { UsersService } from './users.service';
import { AppError } from '../middleware/errorHandler';

const makePrismaMock = () => ({
  user: {
    findUnique: vi.fn(),
    update: vi.fn(),
  },
  vehicle: {
    findUnique: vi.fn(),
    create: vi.fn(),
    update: vi.fn(),
  },
});

describe('UsersService', () => {
  const userId = 'user-1';
  const targetId = 'user-2';
  let prisma: ReturnType<typeof makePrismaMock>;
  let service: UsersService;

  beforeEach(() => {
    prisma = makePrismaMock();
    service = new UsersService(prisma as any);
  });

  describe('getMe', () => {
    it('returns user when found', async () => {
      const expected = { id: userId, email: 'test@uta.edu.ec' };
      prisma.user.findUnique.mockResolvedValue(expected);

      const result = await service.getMe(userId);

      expect(result).toEqual(expected);
      expect(prisma.user.findUnique).toHaveBeenCalledWith({
        where: { id: userId },
        select: expect.any(Object),
      });
    });

    it('throws AppError when user not found', async () => {
      prisma.user.findUnique.mockResolvedValue(null);

      await expect(service.getMe(userId)).rejects.toEqual(
        new AppError(404, 'Usuario no encontrado'),
      );
    });
  });

  describe('updateMe', () => {
    it('updates user with provided data', async () => {
      const payload = { fullName: 'Nuevo Nombre' };
      const expected = { id: userId, fullName: 'Nuevo Nombre' };
      prisma.user.findUnique.mockResolvedValue({ id: userId });
      prisma.user.update.mockResolvedValue(expected);

      const result = await service.updateMe(userId, payload);

      expect(result).toEqual(expected);
      expect(prisma.user.update).toHaveBeenCalledWith({
        where: { id: userId },
        data: payload,
        select: expect.any(Object),
      });
    });
  });

  describe('createVehicle', () => {
    it('creates vehicle when none exists', async () => {
      const payload = {
        brand: 'Toyota',
        model: 'Corolla',
        year: 2020,
        plateNumber: 'ABC1234',
        color: 'Blanco',
      };
      const expected = { id: 'veh-1', ...payload };
      prisma.vehicle.findUnique.mockResolvedValue(null);
      prisma.vehicle.create.mockResolvedValue(expected);

      const result = await service.createVehicle(userId, payload);

      expect(result).toEqual(expected);
      expect(prisma.vehicle.findUnique).toHaveBeenCalledWith({ where: { userId } });
      expect(prisma.vehicle.create).toHaveBeenCalledWith({
        data: { userId, ...payload },
      });
    });

    it('throws AppError when vehicle already exists', async () => {
      prisma.vehicle.findUnique.mockResolvedValue({ id: 'veh-1' });

      await expect(
        service.createVehicle(userId, {
          brand: 'Toyota',
          model: 'Corolla',
          year: 2020,
          plateNumber: 'ABC1234',
          color: 'Blanco',
        }),
      ).rejects.toEqual(
        new AppError(409, 'Ya tienes un vehículo registrado. Usa PATCH para actualizarlo.'),
      );
    });
  });

  describe('updateVehicle', () => {
    it('updates vehicle when it exists', async () => {
      const payload = { color: 'Negro' };
      const expected = { id: 'veh-1', color: 'Negro' };
      prisma.vehicle.findUnique.mockResolvedValue({ id: 'veh-1', userId });
      prisma.vehicle.update.mockResolvedValue(expected);

      const result = await service.updateVehicle(userId, payload);

      expect(result).toEqual(expected);
      expect(prisma.vehicle.findUnique).toHaveBeenCalledWith({ where: { userId } });
      expect(prisma.vehicle.update).toHaveBeenCalledWith({
        where: { userId },
        data: payload,
      });
    });

    it('throws AppError when vehicle does not exist', async () => {
      prisma.vehicle.findUnique.mockResolvedValue(null);

      await expect(service.updateVehicle(userId, { color: 'Negro' })).rejects.toEqual(
        new AppError(404, 'No tienes vehículo registrado. Usa POST para crear uno.'),
      );
    });
  });

  describe('getPublicProfile', () => {
    it('returns public profile when found', async () => {
      const expected = { id: targetId, fullName: 'User 2' };
      prisma.user.findUnique.mockResolvedValue(expected);

      const result = await service.getPublicProfile(targetId);

      expect(result).toEqual(expected);
      expect(prisma.user.findUnique).toHaveBeenCalledWith({
        where: { id: targetId },
        select: expect.any(Object),
      });
    });

    it('throws AppError when public profile not found', async () => {
      prisma.user.findUnique.mockResolvedValue(null);

      await expect(service.getPublicProfile(targetId)).rejects.toEqual(
        new AppError(404, 'Usuario no encontrado'),
      );
    });
  });
});

import { Server, Socket } from 'socket.io';
import { verifyAccessToken } from '../utils/jwt';
import { prisma } from '../config/database';

interface AuthenticatedSocket extends Socket {
  data: {
    userId: string;
    email: string;
    role: string;
  };
}

export function registerTrackingHandlers(io: Server) {
  // ─── Autenticación al conectar ────────────────────────────────────────────
  io.use(async (socket, next) => {
    const token =
      socket.handshake.auth?.token ||
      socket.handshake.headers?.authorization?.replace('Bearer ', '');

    if (!token) {
      return next(new Error('Token requerido'));
    }

    try {
      const payload = verifyAccessToken(token);
      socket.data.userId = payload.userId;
      socket.data.email = payload.email;
      socket.data.role = payload.role;
      next();
    } catch {
      next(new Error('Token inválido o expirado'));
    }
  });

  io.on('connection', (socket: AuthenticatedSocket) => {
    console.log(`[Socket] Conectado: ${socket.data.userId} (${socket.id})`);

    // Cada usuario se une automáticamente a su sala personal para notificaciones
    socket.join(`user:${socket.data.userId}`);

    // ─── Unirse a la sala de un viaje ──────────────────────────────────────
    socket.on('join:trip', async ({ tripId }: { tripId: string }) => {
      if (!tripId) return socket.emit('error', { message: 'tripId requerido' });

      // Solo el conductor o pasajeros aceptados pueden unirse a la sala
      const trip = await prisma.trip.findUnique({ where: { id: tripId } });
      if (!trip) return socket.emit('error', { message: 'Viaje no encontrado' });

      const isDriver = trip.driverId === socket.data.userId;
      const isPassenger = await prisma.tripRequest.findFirst({
        where: { tripId, passengerId: socket.data.userId, status: 'ACCEPTED' },
      });

      if (!isDriver && !isPassenger) {
        return socket.emit('error', { message: 'No tienes acceso a este viaje' });
      }

      socket.join(`trip:${tripId}`);
      socket.emit('joined:trip', { tripId });
      console.log(`[Socket] ${socket.data.userId} se unió a trip:${tripId}`);
    });

    // ─── Salir de la sala de un viaje ──────────────────────────────────────
    socket.on('leave:trip', ({ tripId }: { tripId: string }) => {
      socket.leave(`trip:${tripId}`);
      console.log(`[Socket] ${socket.data.userId} salió de trip:${tripId}`);
    });

    // ─── Conductor emite su ubicación ──────────────────────────────────────
    socket.on('location:update', async ({ tripId, lat, lng }: { tripId: string; lat: number; lng: number }) => {
      if (!tripId || lat === undefined || lng === undefined) {
        return socket.emit('error', { message: 'tripId, lat y lng son requeridos' });
      }

      const trip = await prisma.trip.findUnique({ where: { id: tripId } });
      if (!trip) return socket.emit('error', { message: 'Viaje no encontrado' });
      if (trip.driverId !== socket.data.userId) {
        return socket.emit('error', { message: 'Solo el conductor puede emitir ubicación' });
      }
      if (trip.status !== 'IN_PROGRESS') {
        return socket.emit('error', { message: 'Solo se puede emitir ubicación en viajes IN_PROGRESS' });
      }

      // Emitir a todos en la sala (excepto el conductor)
      socket.to(`trip:${tripId}`).emit('location:update', {
        lat,
        lng,
        timestamp: new Date().toISOString(),
        driverId: socket.data.userId,
      });
    });

    // ─── Desconexión ───────────────────────────────────────────────────────
    socket.on('disconnect', (reason) => {
      console.log(`[Socket] Desconectado: ${socket.data.userId} — ${reason}`);
    });
  });
}

// ─── Helper para emitir desde servicios HTTP ──────────────────────────────────
// Se usa en controllers para notificar cambios de estado en tiempo real
let _io: Server | null = null;

export function setIo(io: Server) {
  _io = io;
}

export function emitToTrip(tripId: string, event: string, data: object) {
  _io?.to(`trip:${tripId}`).emit(event, data);
}

export function emitToUser(userId: string, event: string, data: object) {
  _io?.to(`user:${userId}`).emit(event, data);
}

import bcrypt from 'bcryptjs';
import { randomInt } from 'node:crypto';

const SALT_ROUNDS = 10;

export async function hashPassword(plain: string): Promise<string> {
  return bcrypt.hash(plain, SALT_ROUNDS);
}

export async function comparePassword(plain: string, hashed: string): Promise<boolean> {
  return bcrypt.compare(plain, hashed);
}

export function generateOTP(): string {
  return randomInt(100000, 1000000).toString();
}

import { exec } from 'child_process';
import { promisify } from 'util';
import path from 'path';
import dotenv from 'dotenv';

const execAsync = promisify(exec);

/**
 * Espera a que la base de datos esté lista aceptando conexiones.
 * Reintenta cada 1s hasta maxRetries (default 15).
 */
async function waitForDatabase(env: NodeJS.ProcessEnv, maxRetries = 15): Promise<void> {
  const cwd = path.join(__dirname, '..');
  for (let i = 1; i <= maxRetries; i++) {
    try {
      await execAsync('npx prisma db execute --stdin <<< "SELECT 1"', { cwd, env });
      return;
    } catch {
      if (i === maxRetries) {
        throw new Error(`Base de datos no disponible después de ${maxRetries} segundos`);
      }
      console.log(`⏳ Esperando base de datos... (${i}/${maxRetries})`);
      await new Promise((r) => setTimeout(r, 1000));
    }
  }
}

/**
 * Global setup para Vitest
 * Espera a que Postgres esté listo y luego ejecuta las migraciones de Prisma
 */
export default async function globalSetup() {
  console.log('🔧 Ejecutando migraciones de Prisma para BD de test...');

  // Cargar variables de .env.test
  const envPath = path.join(__dirname, '..', '.env.test');
  dotenv.config({ path: envPath });

  const env = { ...process.env, NODE_ENV: 'test' };
  const cwd = path.join(__dirname, '..');

  // Esperar a que PostgreSQL esté listo antes de migrar
  await waitForDatabase(env);

  try {
    await execAsync('npx prisma migrate deploy', { cwd, env });
    console.log('✅ Migraciones completadas exitosamente');
  } catch (error) {
    console.error('❌ Error ejecutando migraciones:', error);
    throw error;
  }
}

